import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.C3fpVp7C.js";const u=JSON.parse('{"title":"1. Ed25519 JWTs backed by server state","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0001-signed-tokens-with-server-state.md","filePath":"adr/0001-signed-tokens-with-server-state.md","lastUpdated":1792160181000}'),o={name:"adr/0001-signed-tokens-with-server-state.md"};function r(i,e,d,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="_1-ed25519-jwts-backed-by-server-state" tabindex="-1">1. Ed25519 JWTs backed by server state <a class="header-anchor" href="#_1-ed25519-jwts-backed-by-server-state" aria-label="Permalink to &quot;1. Ed25519 JWTs backed by server state&quot;">​</a></h1><p>Status: accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Agents need a credential they can pass to tool servers and to sub-agents. Two families fit: stateless signed tokens, which anyone can verify with a public key, and opaque tokens, which only the issuer can resolve. Agents also need revocation that takes effect at once, use limits and human approvals, which all need shared state.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Tokens are compact JWS values signed with Ed25519 (<code>alg: EdDSA</code>, <code>typ: agent-auth+jwt</code>). The claims carry the agent, principal, grant, canonical scopes, parent token, delegation depth, use limit and expiry. The server also stores every token row in SQLite. An online check verifies the signature, then loads the token&#39;s chain back to the root and rejects it if any ancestor is revoked or expired. The server publishes the public key at <code>/.well-known/jwks.json</code>.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Tool servers choose their trade-off. <code>onlineVerifier()</code> sees revocations, use counts and approvals. <code>offlineVerifier()</code> needs no network call but accepts a revoked token until it expires and denies approval scopes.</li><li>Ed25519 keys are small and fast, and signatures are deterministic.</li><li>Tokens are bearer tokens: there is no proof of possession yet.</li><li>There is one signing key. Rotation needs multiple keys in the JWKS, which is on the roadmap.</li></ul>',8)])])}const k=t(o,[["render",r]]);export{u as __pageData,k as default};
